fn role_from_str(value: &str) -> IntrinsicReconstructionRole {
    match value {
        "canonical-grid" => IntrinsicReconstructionRole::CanonicalGrid,
        "legacy-absolute-envelope" => IntrinsicReconstructionRole::LegacyAbsoluteEnvelope,
        "settled-protected" => IntrinsicReconstructionRole::SettledProtected,
        "reversed-priority" => IntrinsicReconstructionRole::ReversedPriority,
        "endpoint-q0-left-to-right" => IntrinsicReconstructionRole::EndpointQ0LeftToRight,
        "endpoint-q0-right-to-left" => IntrinsicReconstructionRole::EndpointQ0RightToLeft,
        "endpoint-q90-left-to-right" => IntrinsicReconstructionRole::EndpointQ90LeftToRight,
        "endpoint-q90-right-to-left" => IntrinsicReconstructionRole::EndpointQ90RightToLeft,
        "open-pocket-first" => IntrinsicReconstructionRole::OpenPocketFirst,
        "reversed-priority-open-pocket-first" => {
            IntrinsicReconstructionRole::ReversedPriorityOpenPocketFirst
        }
        "endpoint-q0-left-to-right-open-pocket-first" => {
            IntrinsicReconstructionRole::EndpointQ0LeftToRightOpenPocketFirst
        }
        "endpoint-q0-right-to-left-open-pocket-first" => {
            IntrinsicReconstructionRole::EndpointQ0RightToLeftOpenPocketFirst
        }
        "endpoint-q90-left-to-right-open-pocket-first" => {
            IntrinsicReconstructionRole::EndpointQ90LeftToRightOpenPocketFirst
        }
        "endpoint-q90-right-to-left-open-pocket-first" => {
            IntrinsicReconstructionRole::EndpointQ90RightToLeftOpenPocketFirst
        }
        other => panic!("unknown role {other}"),
    }
}

fn role_family_from_str(value: &str) -> IntrinsicReconstructionRoleFamily {
    match value {
        "all" => IntrinsicReconstructionRoleFamily::All,
        "pure-growth" => IntrinsicReconstructionRoleFamily::PureGrowth,
        "gap-contained" => IntrinsicReconstructionRoleFamily::GapContained,
        "endpoint-q90-right-to-left" => IntrinsicReconstructionRoleFamily::EndpointQ90RightToLeft,
        other => panic!("unknown role family {other}"),
    }
}

fn seed_role_from_str(value: &str) -> IntrinsicReconstructionSeedRole {
    match value {
        "canonical-grid" => IntrinsicReconstructionSeedRole::CanonicalGrid,
        "legacy-absolute-envelope" => IntrinsicReconstructionSeedRole::LegacyAbsoluteEnvelope,
        "settled-protected" => IntrinsicReconstructionSeedRole::SettledProtected,
        other => panic!("unknown seed role {other}"),
    }
}

fn candidate_mode_label(mode: IntrinsicStrictCandidateMode) -> &'static str {
    match mode {
        IntrinsicStrictCandidateMode::Comparator(IntrinsicStrictComparatorMode::PureGrowth) => {
            "pure-growth"
        }
        IntrinsicStrictCandidateMode::Comparator(
            IntrinsicStrictComparatorMode::LegacyAbsoluteEnvelope,
        ) => "legacy-absolute-envelope",
        IntrinsicStrictCandidateMode::Comparator(IntrinsicStrictComparatorMode::ContactBand) => {
            "contact-band"
        }
        IntrinsicStrictCandidateMode::GapContained => "gap-contained",
    }
}

