// ===========================================================================
// Vector file shape/coverage floor (mirrors the identically-purposed
// `total_vector_count_meets_the_task_spec_floor`/`total_vector_count_is_at_least_500`
// tests in every sibling `*_vectors.rs` suite in this crate).
// ===========================================================================

#[test]
fn total_vector_count_meets_the_task_spec_floor() {
    let file = load_vectors();
    let total = file["totalVectorCount"]
        .as_u64()
        .expect("totalVectorCount header present");
    let section_counts = [
        ("endpointOrdersCaseCount", "endpointOrdersCases"),
        ("specsCaseCount", "specsCases"),
        ("orderKeyCaseCount", "orderKeyCases"),
        ("archiveCaseCount", "archiveCases"),
        ("portfolioCaseCount", "portfolioCases"),
    ];
    let mut sum = 0u64;
    for (count_field, array_field) in section_counts {
        let declared = file[count_field]
            .as_u64()
            .unwrap_or_else(|| panic!("{count_field} header present"));
        let actual = file[array_field]
            .as_array()
            .unwrap_or_else(|| panic!("{array_field} array present"))
            .len() as u64;
        assert_eq!(
            declared, actual,
            "{count_field} header ({declared}) must match {array_field}.len() ({actual})"
        );
        sum += actual;
    }
    assert_eq!(
        total, sum,
        "totalVectorCount ({total}) must equal the sum of every section's case count ({sum})"
    );
    assert!(
        total >= 300,
        "expected >= 300 reconstruction vectors per the task spec, got {total}"
    );
    let generating_commit = file["generatingCommit"]
        .as_str()
        .expect("generatingCommit header present");
    assert!(
        !generating_commit.is_empty(),
        "vectors file must record its generating commit (ruling R14)"
    );
}

// ===========================================================================
// Section A: `buildCanonicalEndpointOrders`.
// ===========================================================================

#[test]
fn endpoint_orders_cases_reproduce_ts_traversal_orders() {
    let vectors = load_vectors();
    let cases = vectors["endpointOrdersCases"]
        .as_array()
        .expect("endpointOrdersCases array present");
    assert!(!cases.is_empty());

    for case in cases {
        let case_id = case["caseId"].as_str().expect("caseId present");
        let pieces: Vec<Arc<IrregularPreparedPiece>> = case["pieces"]
            .as_array()
            .expect("pieces array present")
            .iter()
            .map(|p| {
                rect_prepared_piece(
                    p["id"].as_str().expect("id present"),
                    decode_f64_bits(p, "width"),
                    decode_f64_bits(p, "height"),
                )
            })
            .collect();
        let piece_by_id: HashMap<String, Arc<IrregularPreparedPiece>> = pieces
            .iter()
            .map(|p| (p.piece_id.clone().unwrap().as_str().to_string(), p.clone()))
            .collect();
        let placed: Vec<Arc<IrregularPlacedPiece>> = case["placements"]
            .as_array()
            .expect("placements array present")
            .iter()
            .map(|p| {
                let id = p["id"].as_str().expect("id present");
                let piece = piece_by_id
                    .get(id)
                    .unwrap_or_else(|| panic!("piece {id} present"));
                rect_place(piece, decode_f64_bits(p, "x"), decode_f64_bits(p, "y"))
            })
            .collect();

        let orders = build_canonical_endpoint_orders(&pieces, &placed);
        let expected_orders = case["orders"].as_object().expect("orders object present");
        for (role_str, expected_ids) in expected_orders {
            let role = role_from_str(role_str);
            let actual = orders
                .iter()
                .find(|order| order.role == role)
                .unwrap_or_else(|| panic!("{case_id}: role {role_str} present"));
            let actual_ids: Vec<String> = actual
                .pieces
                .iter()
                .map(|p| p.piece_id.clone().unwrap().as_str().to_string())
                .collect();
            let expected_ids: Vec<String> = expected_ids
                .as_array()
                .expect("expected ids array")
                .iter()
                .map(|v| v.as_str().expect("id string").to_string())
                .collect();
            assert_eq!(actual_ids, expected_ids, "{case_id}: order {role_str}");
        }
    }
}

