#[test]
fn specs_cases_reproduce_ts_role_order_and_family_counts() {
    let vectors = load_vectors();
    let cases = vectors["specsCases"]
        .as_array()
        .expect("specsCases array present");
    assert!(!cases.is_empty());

    for case in cases {
        let case_id = case["caseId"].as_str().expect("caseId present");
        let pieces: Vec<Arc<IrregularPreparedPiece>> = case["pieces"]
            .as_array()
            .expect("pieces array present")
            .iter()
            .map(|p| {
                rect_prepared_piece(
                    p["id"].as_str().expect("id present"),
                    decode_f64_bits(p, "width"),
                    decode_f64_bits(p, "height"),
                )
            })
            .collect();
        let piece_by_id: HashMap<String, Arc<IrregularPreparedPiece>> = pieces
            .iter()
            .map(|p| (p.piece_id.clone().unwrap().as_str().to_string(), p.clone()))
            .collect();
        let placed: Vec<Arc<IrregularPlacedPiece>> = case["placements"]
            .as_array()
            .expect("placements array present")
            .iter()
            .map(|p| {
                let id = p["id"].as_str().expect("id present");
                let piece = piece_by_id
                    .get(id)
                    .unwrap_or_else(|| panic!("piece {id} present"));
                rect_place(piece, decode_f64_bits(p, "x"), decode_f64_bits(p, "y"))
            })
            .collect();
        let endpoint_hash = case["endpointHash"].as_str().expect("endpointHash present");
        let endpoint = IntrinsicReconstructionSeed {
            role: IntrinsicReconstructionSeedRole::CanonicalGrid,
            canonical_geometry_hash: endpoint_hash.to_string(),
            placed_collision_geometries: placed,
            step_trace: vec![],
            metrics: sample_metrics(endpoint_hash, 5.0),
        };

        let specs: Vec<DecodeSpec> = build_intrinsic_reconstruction_specs(&pieces, &endpoint);
        let expected_role_order: Vec<IntrinsicReconstructionRole> = case["roleOrder"]
            .as_array()
            .expect("roleOrder array present")
            .iter()
            .map(|v| role_from_str(v.as_str().expect("role string")))
            .collect();
        let actual_role_order: Vec<IntrinsicReconstructionRole> =
            specs.iter().map(|spec| spec.role).collect();
        assert_eq!(
            actual_role_order, expected_role_order,
            "{case_id}: role order"
        );

        let gap_contained_count = specs
            .iter()
            .filter(|spec| {
                matches!(
                    spec.candidate_mode,
                    IntrinsicStrictCandidateMode::GapContained
                )
            })
            .count();
        assert_eq!(
            gap_contained_count as u64,
            case["gapContainedCount"]
                .as_u64()
                .expect("gapContainedCount present"),
            "{case_id}: gapContainedCount"
        );

        let pure_growth_family_count = specs
            .iter()
            .filter(|spec| {
                intrinsic_reconstruction_spec_matches_family(
                    spec,
                    IntrinsicReconstructionRoleFamily::PureGrowth,
                )
            })
            .count();
        assert_eq!(
            pure_growth_family_count as u64,
            case["pureGrowthFamilyCount"]
                .as_u64()
                .expect("pureGrowthFamilyCount present"),
            "{case_id}: pureGrowthFamilyCount"
        );

        let gap_contained_family_count = specs
            .iter()
            .filter(|spec| {
                intrinsic_reconstruction_spec_matches_family(
                    spec,
                    IntrinsicReconstructionRoleFamily::GapContained,
                )
            })
            .count();
        assert_eq!(
            gap_contained_family_count as u64,
            case["gapContainedFamilyCount"]
                .as_u64()
                .expect("gapContainedFamilyCount present"),
            "{case_id}: gapContainedFamilyCount"
        );

        let all_family_count = specs
            .iter()
            .filter(|spec| {
                intrinsic_reconstruction_spec_matches_family(
                    spec,
                    IntrinsicReconstructionRoleFamily::All,
                )
            })
            .count();
        assert_eq!(
            all_family_count as u64,
            case["allFamilyCount"]
                .as_u64()
                .expect("allFamilyCount present"),
            "{case_id}: allFamilyCount"
        );

        let focused_family_roles: Vec<IntrinsicReconstructionRole> = specs
            .iter()
            .filter(|spec| {
                intrinsic_reconstruction_spec_matches_family(
                    spec,
                    IntrinsicReconstructionRoleFamily::EndpointQ90RightToLeft,
                )
            })
            .map(|spec| spec.role)
            .collect();
        let expected_focused_family_roles: Vec<IntrinsicReconstructionRole> = case
            ["focusedFamilyRoles"]
            .as_array()
            .expect("focusedFamilyRoles array present")
            .iter()
            .map(|v| role_from_str(v.as_str().expect("role string")))
            .collect();
        assert_eq!(
            focused_family_roles, expected_focused_family_roles,
            "{case_id}: focusedFamilyRoles"
        );
    }
}

