struct AlwaysCancelControl;
impl NfpIfpControl for AlwaysCancelControl {
    fn checkpoint(&mut self, _phase: NfpIfpCheckpointPhase) -> Result<(), NfpIfpControlAbortError> {
        Err(NfpIfpControlAbortError {
            reason: NfpIfpAbortReason::Cancelled,
            message: "cancelled".to_string(),
        })
    }
}

/// Decodes one `IntrinsicStrictLocalScore` recorded by `encodeLocalScore`
/// (`dump-reconstruction.ts`). `exact` is never encoded there (and never
/// compared by `assert_run_matches`'s own step-trace assertions below), so
/// it is always reconstructed as `None` here.
fn local_score_from_json(value: &Value) -> IntrinsicStrictLocalScore {
    IntrinsicStrictLocalScore {
        maximum_side_mm: decode_f64_bits(value, "maximumSideMm"),
        envelope_area_mm2: decode_f64_bits(value, "envelopeAreaMm2"),
        envelope_span_mm: decode_f64_bits(value, "envelopeSpanMm"),
        shared_boundary_length_mm: decode_f64_bits(value, "sharedBoundaryLengthMm"),
        canonical_combined_geometry_key: value["canonicalCombinedGeometryKey"]
            .as_str()
            .expect("canonicalCombinedGeometryKey present")
            .to_string(),
        exact: None,
    }
}

/// Decodes a `stepTrace` array recorded by `encodeStepTrace`
/// (`dump-reconstruction.ts`).
fn step_trace_from_json(value: &Value) -> Vec<IntrinsicStrictStepTrace> {
    value
        .as_array()
        .expect("stepTrace array present")
        .iter()
        .map(|entry| IntrinsicStrictStepTrace {
            piece_id: PieceId::new(entry["pieceId"].as_str().expect("pieceId present")),
            candidate_count: decode_f64_bits(entry, "candidateCount"),
            transform_family_count: decode_f64_bits(entry, "transformFamilyCount"),
            selected_transform_family: entry["selectedTransformFamily"]
                .as_str()
                .map(|value| value.to_string()),
            selected_score: match &entry["selectedScore"] {
                Value::Null => None,
                score => Some(local_score_from_json(score)),
            },
        })
        .collect()
}

/// Decodes an `encodeMetrics` object (`dump-reconstruction.ts`) into
/// `IntrinsicStrictCompletedMetrics`. `runtimeMs` is never encoded (the dump
/// script's own top doc: "diagnostic-only, per characterization §7.5 -- the
/// Rust differential test must not assert on them") and `exact` is never
/// encoded either (never asserted by `assert_metrics_matches`), so both are
/// reconstructed as placeholder/`None` values here.
fn metrics_from_json(value: &Value) -> IntrinsicStrictCompletedMetrics {
    IntrinsicStrictCompletedMetrics {
        envelope_maximum_side_mm: decode_f64_bits(value, "envelopeMaximumSideMm"),
        envelope_area_mm2: decode_f64_bits(value, "envelopeAreaMm2"),
        envelope_span_mm: decode_f64_bits(value, "envelopeSpanMm"),
        enclosed_cavity_count: decode_f64_bits(value, "enclosedCavityCount"),
        total_enclosed_cavity_area_mm2: decode_f64_bits(value, "totalEnclosedCavityAreaMm2"),
        largest_occupied_hull_gap_ratio: decode_f64_bits(value, "largestOccupiedHullGapRatio"),
        isolated_piece_count: decode_f64_bits(value, "isolatedPieceCount"),
        positive_contact_component_count: decode_f64_bits(value, "positiveContactComponentCount"),
        largest_positive_contact_component_size: decode_f64_bits(
            value,
            "largestPositiveContactComponentSize",
        ),
        largest_positive_contact_component_ratio: decode_f64_bits(
            value,
            "largestPositiveContactComponentRatio",
        ),
        occupied_area_outside_largest_contact_component_mm2: decode_f64_bits(
            value,
            "occupiedAreaOutsideLargestContactComponentMm2",
        ),
        occupied_hull_waste_ratio: decode_f64_bits(value, "occupiedHullWasteRatio"),
        total_structural_contacts: decode_f64_bits(value, "totalStructuralContacts"),
        dominant_structural_contacts: decode_f64_bits(value, "dominantStructuralContacts"),
        contact_units: decode_f64_bits(value, "contactUnits"),
        shared_boundary_length_mm: decode_f64_bits(value, "sharedBoundaryLengthMm"),
        canonical_geometry_hash: value["canonicalGeometryHash"]
            .as_str()
            .expect("canonicalGeometryHash present")
            .to_string(),
        runtime_ms: 0.0,
        exact: None,
    }
}

/// Reconstructs one seed placement recorded by `encodeSeedPlacement`
/// (`dump-reconstruction.ts`): looks the piece up by id among this case's
/// already-parsed `pieces` and applies its (sole) transform candidate --
/// every portfolio-case piece carries exactly one (`preparedPiece`'s
/// `transformCount = 1` default) -- exactly mirroring `realPlace`'s own
/// shape.
fn seed_placement_from_json(
    pieces: &[Arc<IrregularPreparedPiece>],
    value: &Value,
) -> Arc<IrregularPlacedPiece> {
    let piece_id = value["pieceId"].as_str().expect("pieceId present");
    let prepared = pieces
        .iter()
        .find(|piece| piece.piece_id.as_ref().map(PieceId::as_str) == Some(piece_id))
        .unwrap_or_else(|| panic!("seed placement pieceId {piece_id} not found among case pieces"))
        .clone();
    let transform = prepared.transforms[0];
    Arc::new(IrregularPlacedPiece {
        placement: IrregularPlacement {
            piece_id: prepared.piece_id.clone(),
            source_piece_id: prepared.source.id.clone(),
            placement_reference: Some(prepared.collision_geometry.placement_reference),
            transform: IrregularTransform {
                translate_x: decode_f64_bits(value, "translateX"),
                translate_y: decode_f64_bits(value, "translateY"),
                rotation_deg: decode_f64_bits(value, "rotationDeg"),
                mirrored: value["mirrored"].as_bool().expect("mirrored bool present"),
            },
        },
        collision_geometry: TransformedCollisionGeometry {
            source_piece_id: prepared.source.id.clone(),
            transform,
            polygon: prepared.collision_geometry.collision_polygon.clone(),
            bounds: prepared.collision_geometry.source_bounds,
        },
    })
}

/// Reconstructs the exact seed `dump-reconstruction.ts` recorded for this
/// case (`case["seed"]`, written by `encodeSeed`) -- see this file's top doc
/// for why this must replay the recorded seed rather than re-derive one via
/// a fresh decode.
fn seed_from_json(
    pieces: &[Arc<IrregularPreparedPiece>],
    case: &Value,
    role: IntrinsicReconstructionSeedRole,
) -> IntrinsicReconstructionSeed {
    let seed_json = &case["seed"];
    let placed_collision_geometries: Vec<Arc<IrregularPlacedPiece>> = seed_json["placements"]
        .as_array()
        .expect("seed.placements array present")
        .iter()
        .map(|placement| seed_placement_from_json(pieces, placement))
        .collect();
    IntrinsicReconstructionSeed {
        role,
        canonical_geometry_hash: seed_json["canonicalGeometryHash"]
            .as_str()
            .expect("seed.canonicalGeometryHash present")
            .to_string(),
        placed_collision_geometries,
        step_trace: step_trace_from_json(&seed_json["stepTrace"]),
        metrics: metrics_from_json(&seed_json["metrics"]),
    }
}

fn assert_metrics_matches(
    actual: Option<&IntrinsicStrictCompletedMetrics>,
    expected: &Value,
    label: &str,
) {
    match (actual, expected) {
        (None, Value::Null) => {}
        (Some(actual), Value::Object(_)) => {
            assert_f64_bits_eq(
                actual.envelope_maximum_side_mm,
                decode_f64_bits(expected, "envelopeMaximumSideMm"),
                &format!("{label}.envelopeMaximumSideMm"),
            );
            assert_f64_bits_eq(
                actual.envelope_area_mm2,
                decode_f64_bits(expected, "envelopeAreaMm2"),
                &format!("{label}.envelopeAreaMm2"),
            );
            assert_f64_bits_eq(
                actual.envelope_span_mm,
                decode_f64_bits(expected, "envelopeSpanMm"),
                &format!("{label}.envelopeSpanMm"),
            );
            assert_f64_bits_eq(
                actual.enclosed_cavity_count,
                decode_f64_bits(expected, "enclosedCavityCount"),
                &format!("{label}.enclosedCavityCount"),
            );
            assert_f64_bits_eq(
                actual.total_enclosed_cavity_area_mm2,
                decode_f64_bits(expected, "totalEnclosedCavityAreaMm2"),
                &format!("{label}.totalEnclosedCavityAreaMm2"),
            );
            assert_f64_bits_eq(
                actual.largest_occupied_hull_gap_ratio,
                decode_f64_bits(expected, "largestOccupiedHullGapRatio"),
                &format!("{label}.largestOccupiedHullGapRatio"),
            );
            assert_f64_bits_eq(
                actual.isolated_piece_count,
                decode_f64_bits(expected, "isolatedPieceCount"),
                &format!("{label}.isolatedPieceCount"),
            );
            assert_f64_bits_eq(
                actual.positive_contact_component_count,
                decode_f64_bits(expected, "positiveContactComponentCount"),
                &format!("{label}.positiveContactComponentCount"),
            );
            assert_f64_bits_eq(
                actual.largest_positive_contact_component_size,
                decode_f64_bits(expected, "largestPositiveContactComponentSize"),
                &format!("{label}.largestPositiveContactComponentSize"),
            );
            assert_f64_bits_eq(
                actual.largest_positive_contact_component_ratio,
                decode_f64_bits(expected, "largestPositiveContactComponentRatio"),
                &format!("{label}.largestPositiveContactComponentRatio"),
            );
            assert_f64_bits_eq(
                actual.occupied_area_outside_largest_contact_component_mm2,
                decode_f64_bits(expected, "occupiedAreaOutsideLargestContactComponentMm2"),
                &format!("{label}.occupiedAreaOutsideLargestContactComponentMm2"),
            );
            assert_f64_bits_eq(
                actual.occupied_hull_waste_ratio,
                decode_f64_bits(expected, "occupiedHullWasteRatio"),
                &format!("{label}.occupiedHullWasteRatio"),
            );
            assert_f64_bits_eq(
                actual.total_structural_contacts,
                decode_f64_bits(expected, "totalStructuralContacts"),
                &format!("{label}.totalStructuralContacts"),
            );
            assert_f64_bits_eq(
                actual.dominant_structural_contacts,
                decode_f64_bits(expected, "dominantStructuralContacts"),
                &format!("{label}.dominantStructuralContacts"),
            );
            assert_f64_bits_eq(
                actual.contact_units,
                decode_f64_bits(expected, "contactUnits"),
                &format!("{label}.contactUnits"),
            );
            assert_f64_bits_eq(
                actual.shared_boundary_length_mm,
                decode_f64_bits(expected, "sharedBoundaryLengthMm"),
                &format!("{label}.sharedBoundaryLengthMm"),
            );
            assert_eq!(
                actual.canonical_geometry_hash,
                expected["canonicalGeometryHash"]
                    .as_str()
                    .expect("canonicalGeometryHash present"),
                "{label}.canonicalGeometryHash"
            );
        }
        (actual, expected) => {
            panic!("{label}: presence mismatch (rust={actual:?} ts={expected:?})")
        }
    }
}

fn assert_run_matches(actual: &IntrinsicReconstructionRun, expected: &Value, label: &str) {
    assert_eq!(
        actual.role.as_str(),
        expected["role"].as_str().unwrap(),
        "{label}.role"
    );
    assert_eq!(
        actual.source_endpoint_hash.as_deref(),
        expected["sourceEndpointHash"].as_str(),
        "{label}.sourceEndpointHash"
    );
    assert_eq!(
        candidate_mode_label(actual.candidate_mode),
        expected["candidateMode"].as_str().unwrap(),
        "{label}.candidateMode"
    );
    let actual_piece_ids: Vec<&str> = actual.piece_ids.iter().map(|id| id.as_str()).collect();
    let expected_piece_ids: Vec<&str> = expected["pieceIds"]
        .as_array()
        .expect("pieceIds array present")
        .iter()
        .map(|v| v.as_str().expect("piece id string"))
        .collect();
    assert_eq!(actual_piece_ids, expected_piece_ids, "{label}.pieceIds");
    assert_eq!(
        actual.effective_order_key,
        expected["effectiveOrderKey"].as_str().unwrap(),
        "{label}.effectiveOrderKey"
    );
    assert_eq!(
        actual.status.as_str(),
        expected["status"].as_str().unwrap(),
        "{label}.status"
    );
    assert_eq!(
        actual.duplicate_of.map(|role| role.as_str()),
        expected["duplicateOf"].as_str(),
        "{label}.duplicateOf"
    );
    assert_optional_f64_bits_eq(
        actual.requested_candidate_evaluations,
        decode_optional_f64_bits(expected, "requestedCandidateEvaluations"),
        &format!("{label}.requestedCandidateEvaluations"),
    );
    assert_optional_f64_bits_eq(
        actual.consumed_candidate_evaluations,
        decode_optional_f64_bits(expected, "consumedCandidateEvaluations"),
        &format!("{label}.consumedCandidateEvaluations"),
    );

    let expected_placements = expected["placements"]
        .as_array()
        .expect("placements array present");
    assert_eq!(
        actual.placed_collision_geometries.len(),
        expected_placements.len(),
        "{label}.placements.len"
    );
    for (index, (actual_placed, expected_placement)) in actual
        .placed_collision_geometries
        .iter()
        .zip(expected_placements.iter())
        .enumerate()
    {
        let sub_label = format!("{label}.placements[{index}]");
        assert_eq!(
            actual_placed.placement.source_piece_id.as_str(),
            expected_placement["pieceId"].as_str().unwrap(),
            "{sub_label}.pieceId"
        );
        assert_f64_bits_eq(
            actual_placed.placement.transform.translate_x,
            decode_f64_bits(expected_placement, "translateX"),
            &format!("{sub_label}.translateX"),
        );
        assert_f64_bits_eq(
            actual_placed.placement.transform.translate_y,
            decode_f64_bits(expected_placement, "translateY"),
            &format!("{sub_label}.translateY"),
        );
        assert_f64_bits_eq(
            actual_placed.placement.transform.rotation_deg,
            decode_f64_bits(expected_placement, "rotationDeg"),
            &format!("{sub_label}.rotationDeg"),
        );
        assert_eq!(
            actual_placed.placement.transform.mirrored,
            expected_placement["mirrored"].as_bool().unwrap(),
            "{sub_label}.mirrored"
        );
    }

    let expected_step_trace = expected["stepTrace"]
        .as_array()
        .expect("stepTrace array present");
    assert_eq!(
        actual.step_trace.len(),
        expected_step_trace.len(),
        "{label}.stepTrace.len"
    );
    for (index, (actual_entry, expected_entry)) in actual
        .step_trace
        .iter()
        .zip(expected_step_trace.iter())
        .enumerate()
    {
        let sub_label = format!("{label}.stepTrace[{index}]");
        assert_eq!(
            actual_entry.piece_id.as_str(),
            expected_entry["pieceId"].as_str().unwrap(),
            "{sub_label}.pieceId"
        );
        assert_f64_bits_eq(
            actual_entry.candidate_count,
            decode_f64_bits(expected_entry, "candidateCount"),
            &format!("{sub_label}.candidateCount"),
        );
        assert_f64_bits_eq(
            actual_entry.transform_family_count,
            decode_f64_bits(expected_entry, "transformFamilyCount"),
            &format!("{sub_label}.transformFamilyCount"),
        );
        assert_eq!(
            actual_entry.selected_transform_family.as_deref(),
            expected_entry["selectedTransformFamily"].as_str(),
            "{sub_label}.selectedTransformFamily"
        );
        match (
            &actual_entry.selected_score,
            &expected_entry["selectedScore"],
        ) {
            (None, Value::Null) => {}
            (Some(score), Value::Object(_)) => {
                let expected_score = &expected_entry["selectedScore"];
                assert_f64_bits_eq(
                    score.maximum_side_mm,
                    decode_f64_bits(expected_score, "maximumSideMm"),
                    &format!("{sub_label}.selectedScore.maximumSideMm"),
                );
                assert_f64_bits_eq(
                    score.envelope_area_mm2,
                    decode_f64_bits(expected_score, "envelopeAreaMm2"),
                    &format!("{sub_label}.selectedScore.envelopeAreaMm2"),
                );
                assert_f64_bits_eq(
                    score.envelope_span_mm,
                    decode_f64_bits(expected_score, "envelopeSpanMm"),
                    &format!("{sub_label}.selectedScore.envelopeSpanMm"),
                );
                assert_f64_bits_eq(
                    score.shared_boundary_length_mm,
                    decode_f64_bits(expected_score, "sharedBoundaryLengthMm"),
                    &format!("{sub_label}.selectedScore.sharedBoundaryLengthMm"),
                );
                assert_eq!(
                    score.canonical_combined_geometry_key,
                    expected_score["canonicalCombinedGeometryKey"]
                        .as_str()
                        .unwrap(),
                    "{sub_label}.selectedScore.canonicalCombinedGeometryKey"
                );
            }
            (actual, expected) => panic!(
                "{sub_label}.selectedScore: presence mismatch (rust={actual:?} ts={expected:?})"
            ),
        }
    }

    let expected_gap_fill_evidence = expected["gapFillEvidence"]
        .as_array()
        .expect("gapFillEvidence array present");
    assert_eq!(
        actual.gap_fill_evidence.len(),
        expected_gap_fill_evidence.len(),
        "{label}.gapFillEvidence.len"
    );
    for (index, (actual_entry, expected_entry)) in actual
        .gap_fill_evidence
        .iter()
        .zip(expected_gap_fill_evidence.iter())
        .enumerate()
    {
        let sub_label = format!("{label}.gapFillEvidence[{index}]");
        assert_eq!(
            actual_entry.piece_id.as_str(),
            expected_entry["pieceId"].as_str().unwrap(),
            "{sub_label}.pieceId"
        );
        assert_eq!(
            actual_entry.region_key,
            expected_entry["regionKey"].as_str().unwrap(),
            "{sub_label}.regionKey"
        );
        assert_f64_bits_eq(
            actual_entry.region_area_before_mm2,
            decode_f64_bits(expected_entry, "regionAreaBeforeMm2"),
            &format!("{sub_label}.regionAreaBeforeMm2"),
        );
        assert_f64_bits_eq(
            actual_entry.region_area_after_mm2,
            decode_f64_bits(expected_entry, "regionAreaAfterMm2"),
            &format!("{sub_label}.regionAreaAfterMm2"),
        );
        assert_f64_bits_eq(
            actual_entry.envelope_maximum_side_delta_mm,
            decode_f64_bits(expected_entry, "envelopeMaximumSideDeltaMm"),
            &format!("{sub_label}.envelopeMaximumSideDeltaMm"),
        );
        assert_f64_bits_eq(
            actual_entry.envelope_area_delta_mm2,
            decode_f64_bits(expected_entry, "envelopeAreaDeltaMm2"),
            &format!("{sub_label}.envelopeAreaDeltaMm2"),
        );
        assert_f64_bits_eq(
            actual_entry.shared_boundary_length_mm,
            decode_f64_bits(expected_entry, "sharedBoundaryLengthMm"),
            &format!("{sub_label}.sharedBoundaryLengthMm"),
        );
        assert_eq!(
            actual_entry.non_inert,
            expected_entry["nonInert"].as_bool().unwrap(),
            "{sub_label}.nonInert"
        );
    }

    assert_metrics_matches(
        actual.metrics.as_ref(),
        &expected["metrics"],
        &format!("{label}.metrics"),
    );
}

#[test]
fn portfolio_cases_reproduce_ts_outcomes() {
    let vectors = load_vectors();
    let cases = vectors["portfolioCases"]
        .as_array()
        .expect("portfolioCases array present");
    assert!(!cases.is_empty());
    let settings = settings();

    for case in cases {
        let case_id = case["caseId"].as_str().expect("caseId present");
        let pieces = prepared_pieces_full_from_json(&case["pieces"]);
        let seed_role = seed_role_from_str(case["seedRole"].as_str().expect("seedRole present"));
        let role_family =
            role_family_from_str(case["roleFamily"].as_str().expect("roleFamily present"));

        let seed = seed_from_json(&pieces, case, seed_role);

        let maximum_runtime_ms_per_decode =
            decode_optional_f64_bits(case, "maximumRuntimeMsPerDecode");
        let maximum_total_runtime_ms = decode_optional_f64_bits(case, "maximumTotalRuntimeMs");
        let maximum_candidate_evaluations_per_decode =
            decode_optional_f64_bits(case, "maximumCandidateEvaluationsPerDecode");
        let maximum_total_candidate_evaluations =
            decode_optional_f64_bits(case, "maximumTotalCandidateEvaluations");

        let is_cancellation_case = case_id.starts_with("cancel");
        let mut cancel_control = AlwaysCancelControl;
        let control: Option<&mut dyn NfpIfpControl> = if is_cancellation_case {
            Some(&mut cancel_control)
        } else {
            None
        };

        let mut geometry_cache = GeometryCacheStore::new();
        let result = run_intrinsic_reconstruction_portfolio(
            RunIntrinsicReconstructionPortfolioInput {
                all_prepared_pieces: &pieces,
                baseline_seeds: std::slice::from_ref(&seed),
                maximum_runtime_ms_per_decode,
                maximum_total_runtime_ms,
                role_family: Some(role_family),
                maximum_candidate_evaluations_per_decode,
                maximum_total_candidate_evaluations,
                control,
                timing_now: None,
            },
            &settings,
            &mut geometry_cache,
        );

        let outcome = &case["outcome"];
        let kind = outcome["kind"].as_str().expect("outcome.kind present");
        match kind {
            "success" => {
                let portfolio_result =
                    result.unwrap_or_else(|err| panic!("{case_id}: expected success, got {err:?}"));
                let expected = &outcome["result"];
                let expected_runs = expected["runs"].as_array().expect("runs array present");
                assert_eq!(
                    portfolio_result.runs.len(),
                    expected_runs.len(),
                    "{case_id}: runs.len"
                );
                for (index, (actual_run, expected_run)) in portfolio_result
                    .runs
                    .iter()
                    .zip(expected_runs.iter())
                    .enumerate()
                {
                    assert_run_matches(
                        actual_run,
                        expected_run,
                        &format!("{case_id}.runs[{index}]"),
                    );
                }

                let expected_archive = expected["archive"]
                    .as_array()
                    .expect("archive array present");
                assert_eq!(
                    portfolio_result.archive.len(),
                    expected_archive.len(),
                    "{case_id}: archive.len"
                );
                for (index, (actual_entry, expected_entry)) in portfolio_result
                    .archive
                    .iter()
                    .zip(expected_archive.iter())
                    .enumerate()
                {
                    assert_run_matches(
                        &actual_entry.run,
                        expected_entry,
                        &format!("{case_id}.archive[{index}]"),
                    );
                }

                match (&portfolio_result.winner, &expected["winner"]) {
                    (None, Value::Null) => {}
                    (Some(winner), expected_winner) => {
                        assert_run_matches(
                            &winner.run,
                            expected_winner,
                            &format!("{case_id}.winner"),
                        );
                    }
                    (actual, expected) => panic!(
                        "{case_id}.winner: presence mismatch (rust={actual:?} ts={expected:?})"
                    ),
                }

                assert_f64_bits_eq(
                    portfolio_result.consumed_candidate_evaluations,
                    decode_f64_bits(expected, "consumedCandidateEvaluations"),
                    &format!("{case_id}.consumedCandidateEvaluations"),
                );
                assert_eq!(
                    portfolio_result.candidate_evaluation_accounting_complete,
                    expected["candidateEvaluationAccountingComplete"]
                        .as_bool()
                        .unwrap(),
                    "{case_id}.candidateEvaluationAccountingComplete"
                );
            }
            "failure" => {
                let err = match result {
                    Err(err) => err,
                    Ok(_) => panic!("{case_id}: expected failure, got success"),
                };
                let expected_tag = outcome["tag"].as_str().expect("outcome.tag present");
                let expected_reason = outcome["reason"].as_str();
                match err {
                    IntrinsicReconstructionPortfolioFailure::Strict(
                        irregular_nesting_native::search::strict_decoder::IntrinsicStrictDecoderFailure::Abort(
                            abort,
                        ),
                    ) => {
                        assert_eq!(
                            expected_tag, "IrregularNfpIfpControlAbortError",
                            "{case_id}: failure tag"
                        );
                        let reason_str = match abort.reason {
                            NfpIfpAbortReason::Cancelled => "cancelled",
                            NfpIfpAbortReason::Deadline => "deadline",
                        };
                        assert_eq!(Some(reason_str), expected_reason, "{case_id}: abort reason");
                    }
                    other => panic!("{case_id}: unexpected failure shape {other:?}"),
                }
            }
            other => panic!("{case_id}: unknown outcome kind {other}"),
        }
    }
}
